CREATE FUNCTION cmd_validate_actor_language() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE level integer; used integer; BEGIN IF NEW.proficiency_kind='additional' THEN SELECT s.skill_level INTO level FROM actor_skill s JOIN rule_linguistics_mechanic r ON r.skill_rule_id=s.skill_rule_id WHERE s.actor_id=NEW.actor_id; SELECT count(*) INTO used FROM actor_language_proficiency WHERE actor_id=NEW.actor_id AND proficiency_kind='additional'; IF level IS NULL OR used>=level THEN RAISE EXCEPTION 'Additional languages cannot exceed Linguistics level'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER actor_language_valid BEFORE INSERT ON actor_language_proficiency FOR EACH ROW EXECUTE FUNCTION cmd_validate_actor_language();
CREATE FUNCTION cmd_validate_actor_language_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p actor_language_proficiency%ROWTYPE; BEGIN SELECT * INTO STRICT p FROM actor_language_proficiency WHERE source_command_id=NEW.command_id; IF p.actor_id<>NEW.actor_id OR p.language_id<>NEW.language_id OR p.proficiency_kind<>NEW.proficiency_kind OR (NEW.proficiency_kind='additional' AND NEW.linguistics_level<>(SELECT skill_level FROM actor_skill s JOIN rule_linguistics_mechanic r ON r.skill_rule_id=s.skill_rule_id WHERE s.actor_id=NEW.actor_id)) THEN RAISE EXCEPTION 'Actor language receipt mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cmd_actor_language_valid BEFORE INSERT ON cmd_actor_language_receipt FOR EACH ROW EXECUTE FUNCTION cmd_validate_actor_language_receipt();
